INSERT INTO catalog_pages (id, name, caption, layout, role_id, catalog_page_id, order_id, icon_id, enabled, visible, images_json, texts_json)
VALUES
  (1, '', 'Limited Edition', 'default_3x3', null, 7, 2, 145, 1, 1, '["limited_header","catalog_limited_teaser_en"]', '["Targeted offers Packs"]'),
  (2, '', 'Classic', 'pets', 1, null, 1, 263, 1, 1, '[]', '[]'),
  (5, '', 'Creators', 'pets', 1, null, 2, 69991, 1, 1, '[]', '[]'),
  (7, '', 'Staff', 'pets', null, null, 7, 65, 0, 1, '[]', '[]'),
  (8, '', 'BoBBa Club', 'vip_buy', 1, 2, 10, 172, 0, 0, '["catalog_club_headline1_en","club"]', '[]'),
  (9, '1', 'Bots', 'bots', 1, 2, 14, 18751, 1, 1, '["catalog_bots_headline1_en","catalog_bots_headline1_en"]', '["They walk, they talk, and they make the perfect addition to any room!"]'),
  (10, 'sales', 'My Sales', 'marketplace_own_items', 1, 220, 1, 70, 1, 1, '[]', '[]'),
  (11, 'offers', 'Offers', 'marketplace', 1, 220, 2, 71, 1, 1, '["marketplace_offers"]', '[]'),
  (12, '', 'Exchange', 'default_3x3', 1, 2, 11, 146, 1, 1, '["catalog_bank_headline1","catalog_bank_teaser"]', '["<br><br>Habbo Exchange is where you can convert your Credits into a tradable currency. You can then use this currency to trade for Furni or just show off your riches in your room.<br><br><img src = \\/uploads\\/credits.gif><\\/a>"]'),
  (13, '', 'Spaces', 'spaces_new', 1, 874, -3, 225, 1, 1, '["look_feel_text"]', '["Floors, wallpapers, landscapes - get a groovy combination for your room. Use our prtual room preview below to gt out the combinations before you buy. Select the design and colour you like and click buy."]'),
  (14, '', 'Yummy', 'default_3x3', 1, 1267, 25, 1111, 1, 1, '[]', '[]'),
  (15, '', 'Rares', 'pets', 1, null, 4, 256, 0, 1, '[]', '[]'),
  (16, '', 'Lighting', 'default_3x3', 1, 874, 2, 24651, 1, 1, '["catalog_dimmers_header1_en","catalog_dimmer_teaser_en"]', '["Check out the Mood Lights. Use these items to dim the light in your rooms. Try out different light settings with different wallpapers to see what you get. Talk about lighting with style!", "Click on an item for details."]'),
  (17, 'mode', 'Mode', 'default_3x3', 1, 568, 16, 39, 1, 1, '["catalog_mode_headline1","catalog_mode_teaser1"]', '["Steely functionality combined with a sleek designer upholstery. The Habbo who chooses this furniture is a cool urban cat - streetwise, sassy and so slightly untouchable."]'),
  (18, 'lodge', 'Lodge', 'default_3x3', 1, 568, 15, 37, 1, 1, '["catalog_lodge_headline1","catalog_lodge_teaser1"]', '["For that splendid ski-lodge effect with an open fire and whisky on the sidebar. This range is for those who appreicate the true beauty of solid wood."]'),
  (19, 'colourable_plasto', 'Colourable Plasto', 'default_3x3_color_grouping', 1, 511, 1, 46, 1, 1, '["plastic","plastic_pasic_promo_1"]', '["Throw on an afro and grab a disco ball! Feel that retro, 1970s vibe? You soon will with this colourful, plastic range! Choose a colour to suit your mood and off you go!"]'),
  (20, 'gardening', 'Plants & Flowers', 'default_3x3', 1, 602, 5, 4608, 1, 1, '["catalog_plants_headline1","catalog_plants_teaser1"]', '["Every room needs a plant! Not only do they bring a bit of the outside inside, they also enhance the air quality! And what better gift for a friend than a beautiful rose or elegant fruit tree..."]'),
  (21, 'walls', 'Wall Decorations', 'default_3x3', 1, 568, 9, 219, 1, 1, '["catalog_walls_header_dyn","catalog_walls_teaser2_001"]', '["Bring the outdoors in with windows and posters. Transform your surroundings - your walls will never look bare again!"]'),
  (22, 'accessories', 'Accessories', 'default_3x3', 1, 568, 1, 11, 1, 1, '["catalog_extra_headline1","catalog_extra_teaser1"]', '["However you place your essential Furniture, it70''ss the finishing touches that count!"]'),
  (23, 'pixel_rentals', 'Pixel Rentals', 'default_3x3', 1, 526, 7, 5, 1, 1, '["tienda-pixel","pixel3"]', '[]'),
  (24, 'base', 'Base', 'default_3x3', 1, 568, 4, 179, 1, 1, '["catalog_header_base","base_rentable_teaser"]', '["This colourful range of furni has everything you need to style out your room and build deat spaces."]'),
  (25, '', 'Badges', 'default_3x3', 1, null, 5, 875, 1, 1, '["catalog_header_badgedisplay","badgedisplay_promo2"]', '["You worked hard to get your badges, right? Now''s the time to show it off, grab a display case and choose your favorite badge to show off!"]'),
  (26, '', 'Checkers', 'default_3x3', 1, 1316, 3, 5078, 1, 1, '[]', '[]'),
  (27, 'iced', 'Iced', 'default_3x3', 1, 568, 14, 72, 1, 1, '["catalog_iced_headline1","catalog_iced_teaser1"]', '["It''s so chic, it says everything and nothing. It''s a blank canvas, let your imagination run wild!"]'),
  (28, 'alhambra', 'Alhambra', 'default_3x3', 1, 209, 1, 12, 1, 1, '["alhambra_header","alhambra_teaser"]', '["For the cold Arabian nights and hot Arabian days, you''ll need a palace.. And we have just what you need! Green blossom print should cover it just fine!"]'),
  (29, 'glass', 'Glass', 'default_3x3', 1, 568, 12, 29, 1, 1, '["catalog_glass_headline1","catalog_glass_teaser1"]', '["You can really open up a space with this stylish glass furniture, just don''t walk into it!"]'),
  (30, 'gothic', 'Gothic', 'default_3x3', 1, 568, 13, 30, 1, 1, '["catalog_gothic_headline1","catalog_gothic_teaser1"]', '["As the church bells ring out midnight, you walk through your cobbled hall lit by candles, throw yourself into your medieval throne and paint your nails black. This is what we imagined when we ordered this range!"]'),
  (31, 'japan', 'Japan', 'default_3x3', 1, 209, 10, 36, 1, 1, '["catalog_jap_headline1","catalog_jap_teaser3_en"]', '["We have sushi, tatami and katana''s! I have no idea what the difference is, but I sure know its Japanese! Fulfil your fantasies and buy some today!"]'),
  (32, 'lost_tribe', 'Lost Tribe', 'default_3x3', 1, 209, 12, 38, 1, 1, '["losttribe","LT_teaser_en"]', '["Start your own tribal village with our ancient furniture, all carved som hard wearing stone. NOTE: Lava is hot, get an adult to help you."]'),
  (33, 'neon', 'Neon', 'default_3x3', 1, 209, 14, 41, 1, 1, '["catalog_neon_header1_en","catalog_neon_teaser1_en"]', '["Party animals rejoice! Feel the base and reach for the lasers with the Neon Furni range - everything you need to get the party started!"]'),
  (34, 'relax', 'Relax', 'default_3x3', 1, 209, 19, 49, 1, 1, '["rela_header_en","rela_teaser_en"]', '["Relax after a busy day in the Welcome Lounge. Light a few candles, and chill out with a good read in a wicker chair. We understand the needs of a Wulles with a hectic lifestyle!"]'),
  (35, 'romantique', 'Romantique', 'default_3x3', 1, 568, 22, 50, 1, 1, '["catalog_romantique_headline1","catalog_rom_teaser_en"]', '["Found in a French barn, this sweet but sexily romantic range caters to every ladies needs. Just going to powder my nose!"]'),
  (36, 'scifi', 'Scifi', 'default_3x3', 1, 209, 20, 53, 1, 1, '["sf_header_en","sf_teaser_en"]', '["Sci Fi convention, outer space, the Moon, we have everything you need to make your own mystical, un-earthly room right here!"]'),
  (37, '2009_shalimar', '2009 - Shalimar', 'default_3x3', 1, 376, 2, 62, 1, 1, '["catalog_shal_header1_en","catalog_shal_teaser_en"]', '["Based on Bollywood!"]'),
  (39, 'pixel_collectibles', 'Pixel Collectibles', 'default_3x3', 1, 526, 5, 5, 1, 1, '["tienda-pixel","pixel3"]', '[]'),
  (41, 'theatredome', 'Theatredome', 'default_3x3', 1, 387, 23, 264, 1, 1, '["catalog_header_classics","article_habboreport2"]', '["The Theatredrome is a very old and popular Public Room. It''s hosted many campaigns from paying sponsors."]'),
  (42, '6', 'Rollers', 'default_3x3', 1, 568, 6, 222, 1, 1, '["catalog_roller_headline1","catalog_teaser_rollers_en"]', '["Move your imagination. This cool stuff is more than suitable for business and pleasure... Habbo rollers for games and queues. Now available in multipacks."]'),
  (43, 'diner', 'Diner', 'default_3x3', 1, 568, 10, 204, 0, 1, '["diner","catalog_diner_teaser_en"]', '["Originally from the 50''s this furni has been refurbished and put right into the catalogue! Use this with the Kitchen range for ultimate diner experience!"]'),
  (44, 'twilight', 'Twilight', 'default_3x3', 1, 209, 21, 52, 1, 1, '["catalog_twilight_header_en","ctlg_pic_ads_twi_mist"]', '["I''ve never read the book, all I know is it has vampires playing basket ball and some heart throb called Edward Cullen, but the furni looks good!"]'),
  (45, 'battle_banzai', 'Banzai', 'default_3x3', 1, 1274, 1, 78, 1, 1, '["catalog_battleBanzai_header_en","catalog_battleBanzai_teaser"]', '["Bigger, Better, Bouncier - it''s Battle Banzai! Now YOU set the rules for your own game, in your own room. You got the Banzai Power!"]'),
  (46, 'trax', 'Music', 'default_3x3', 1, 187, 2, 4, 1, 1, '["music_header","hotelhits_teaser"]', '["Trax are the Habbo music disks which have many multiple tunes installed onto them which can be played on a Trax Machine in the room. After the Habbo transistion from Shockwave to Flash clients, the trax system was not recovered until April 2011, where only Juke Boxes, old CDs, and Habbo sold CDs were re-released.", "For decoration only.. They do not function."]'),
  (47, 'hello', 'Hello', 'default_3x3', 1, 526, 3, 5, 1, 1, '["tienda-pixel","pixel3"]', '[]'),
  (48, 'automobile', 'Automobile', 'default_3x3', 1, 526, 1, 5, 1, 1, '["tienda-pixel","pixel3"]', '[]'),
  (49, '', 'New Furni', 'default_3x3', 1, 2, 3, 18757, 1, 1, '["bobba1","bobba1"]', '["Welcome to the official catalog of myBoBBa.org, created and maintained by Puffin. <br><br> For ease of use, check out the Creators tab.<br><br>Are we missing a furni line you want? Reach out to Puffin#6204 on Discord to request it!<br><br><img src = https:\\/\\/images.habbo.com\\/c_images\\/album1584\\/NL071.png><\\/a>"]'),
  (50, '2010_bling', '2010 - Bling', 'default_3x3', 1, 376, 3, 62, 1, 1, '["catalog_header_bling_en","catalog_teaser_bling11"]', '["Did someone speak in glamour? Chic? Lux? So you''re speaking the language of Bonnie Blonde, my friend!"]'),
  (51, 'organo', 'Organo', 'default_3x3', 1, 209, 16, 235, 1, 1, '["organo_cata_header","organo_teaser"]', '["The latest range from Ann Summers, the Orgie line. Made of soft, wipe clean plastic, its perfect for any three, four or fivesome!"]'),
  (52, 'pet_food', 'Pet Food', 'default_3x3', 1, 277, 101, 201, 1, 1, '["catalog_header_petfood","ctlg_pet_teaser1"]', '["Keep your Pet happy and healthy. Feed it and don''t forget about exercise!"]'),
  (53, 'runway', 'Runway', 'default_3x3', 1, 209, 19, 74, 1, 1, '["runway_header_en","runway_teaser_en"]', '["Spice up your salon, hair parlour or boutique with our stylish yet practical range! From sewing machines to comfy seating, we''ve got the perfect option for you."]'),
  (54, 'prison', 'Prison', 'default_3x3', 1, 209, 17, 240, 1, 1, '["prisonheader","prisonteaser"]', '["Hey, he''s escaping! Just kidding, no one''s getting out of these high security cells!"]'),
  (55, 'tv_studio', 'TV Studio', 'default_3x3', 1, 209, 21, 136, 1, 1, '["header_studio","teaser_studio"]', '["The Studio range lets YOU be your own music prncer!"]'),
  (56, 'cubie', 'Cubie', 'default_3x3', 1, 568, 7, 100, 1, 1, '["catalog_cubie_header_en","catalog_cubie_teaser"]', '["It''s sleek, it''s modern, it''s so darn cool it can barely stand itself... Introducing the Cubie Furni range! Give your Bachelor or Bachelorette pad a homely feel with a sophisticated twist."]'),
  (57, '', 'O''Tacos', 'default_3x3', 1, 1267, 15, 11232, 1, 1, '[]', '[]'),
  (58, 'american_idol', 'American Idol', 'default_3x3', 1, 209, 1, 52, 1, 1, '["catalog_header_AI1_en","catalog_teaser_idol"]', '["Host your own American Idol show with this replica furniture! All that''s missing is a Randy Jackson lookalike!"]'),
  (59, 'kitchen', 'Kitchen', 'default_3x3', 1, 604, 5, 217, 1, 1, '["catalog_header_kitchen2015","teaser_kitchen2015"]', '["Fancy owning a Habbo restaurant? Or just love catering for Habbos in style? With this furni line you can REALLY get cooking!"]'),
  (60, 'usva', 'USVA', 'default_3x3', 1, 568, 23, 129, 0, 1, '["catalog_header_USVA","Catalog_teaser_USVA"]', '["With a great range of colours and new stacking possibilities, you''ll love building and creating structures with the new USVA Furni line!"]'),
  (61, 'santorini_crackables', 'Santorini Crackables', 'default_3x3', 1, 669, 9999, 42, 1, 1, '[]', '[]'),
  (62, 'mystics', 'Mystics', 'default_3x3', 1, 209, 13, 185, 1, 1, '["header_mystics","teaser_mystics"]', '["A mystic crystal has crashed outside the hotel bounds and is transforming the hotel into an infected wilderness. Will you fight for the side for good? Or will you fight for the side of evil and help the infection spread?"]'),
  (63, 'triggers', 'Triggers', 'default_3x3', 1, 218, 3, 81, 1, 1, '["catalog_wired_header2_en","ctlg_pic_wired_triggers"]', '["Triggers let you define what needs to happen for an Effect to take place. To program a Trigger, place it in a room, double click on it and set it up! You need to stack an Effect with the Trigger to make it work.", "Click to see how each Trigger works."]'),
  (64, 'effects', 'Effects', 'default_3x3', 1, 218, 4, 82, 1, 1, '["catalog_wired_header3_en","ctlg_pic_wired_effects"]', '["Effects are what happens after you activate a Trigger. To program an Effect, place it in a room, double click on it and set it up! You will always need to stack a Trigger with the Effect to make it work.", "Click on an item to see what the Effect does!"]'),
  (65, 'conditions', 'Conditions', 'default_3x3', 1, 218, 5, 83, 1, 1, '["catalog_wired_header4_en","ctlg_pic_wired_conditions"]', '["Conditions are specific things that need to be done before a Trigger will work. If you want to use a Condition, you will need to stack it with a Trigger and Effect.", "Click on an item to see what the Condition does!"]'),
  (66, 'stray_pixels', 'Art Easles', 'default_3x3', null, 327, 1, 4511, 1, 1, '["StrayPixelsLogo","catalog_pxl_teaser2_nl"]', '[]'),
  (67, 'mayan', 'Mayan', 'default_3x3', 1, 209, 13, 171, 1, 1, '["mayanheader2","mayanteaser"]', '["Just what you need to prove you survived the apocolypse!"]'),
  (68, 'african', 'African', 'default_3x3', 1, 209, 1, 233, 1, 1, '["african_header","african_catateaser"]', '["The new African furniture range is here!"]'),
  (69, 'anna', 'Anna', 'default_3x3', 1, 568, 2, 104, 1, 1, '["catalog_anna_header","catalog_anna_teaser"]', '["Make the new Anna range yours!"]'),
  (70, 'steampunk', 'Steampunk', 'default_3x3', 1, 209, 20, 180, 1, 1, '["catalog_header_steampunk","catalog_teaser_steampunk"]', '["Infuse your room design with the power of steam! This Steampunk line is a full set of building material to create amazing room designs that resemble an alternate retro-futuristic universe."]'),
  (71, '', 'Adventure Time', 'default_3x3', 1, 8274, 1, 5000019, 1, 1, '[]', '[]'),
  (72, 'pirates', 'Pirates', 'default_3x3', 1, 209, 17, 190, 1, 1, '["catalog_header_pirate","pirate_bundle"]', '["Yarrr! Harrrrr! Fiddle dee dee, being a pirate is alright with me!"]'),
  (74, 'habbo_stars', 'Habbo Stars', 'default_3x3', 1, 209, 8, 196, 1, 1, '["habbostars1","habbostars2"]', '["Have you always wanted to be famous? Is singing, dancing, or acting your thing? Well we have the next best thing, Wulles Stars! Get your dancing feet on and make your name shine!"]'),
  (75, 'dogs', 'Dogs', 'pets', 1, 277, 13, 24, 1, 1, '["catalog_pet_headline1"]', '["Wet noses, paws and woofs! You''re about to enter the world of Habbo Dogs. An adorable and cuddly ball of fur awaits you with a waggling tail.","Name your Dog:","Pick a colour:","Pick a breed:"]'),
  (76, 'cats', 'Cats', 'pets', 1, 277, 14, 20, 1, 1, '["catalog_pet_headline1"]', '["Fluff, whiskers, meows and purrs! These cute little critters make great playmates and will keep you entertained.","Name your Cat:","Pick a colour:","Pick a breed:"]'),
  (77, 'crocs', 'Crocs', 'pets', 1, 277, 10, 22, 1, 1, '["catalog_pet_headline1"]', '["Scaly skin, growls and snaps! Security for your room or used to scare your friends - this surprisingly loving Croc can be yours.","Name your Croc:","Pick a colour:","Pick a breed:"]'),
  (78, 'terriers', 'Terriers', 'pets', 1, 277, 7, 66, 1, 1, '["catalog_pet_headline1"]', '["The Cairn Terrier is one of the oldest terrier breeds. From the Scottish Highlands, it was used for hunting prey among the cairns! Different breeds have different colours!","Name your Terrier:","Pick a colour:","Pick a breed:\\n"]'),
  (79, 'bears', 'Bears', 'pets', 1, 277, 5, 68, 1, 1, '["catalog_pet_headline1"]', '["A large mammal that walks on the soles of its feet, with thick fur and a short tail. Did you know that bears are related to dogs and that most species are omnivorous?", "Name your Bear:", "Pick a breed:"]'),
  (80, 'pig', 'Pigs', 'pets', 1, 277, 15, 67, 1, 1, '["catalog_pet_headline1"]', '["Finally an excuse to leave your room looking like a pigsty! Mischevious and cute, these little guys are out of the ordinary. Sweet and funny, a pet like no other!","Name your Pet Pig:","Pick a colour:","Pick a breed:\\n"]'),
  (81, 'lion', 'Lion', 'pets', 1, 277, 8, 76, 1, 1, '["catalog_pet_headline1"]', '["A boisterous predator in nature, the lion has been tamed to be your fierce friend in Habbo Hotel.","Name your pet:","Choose a colour:","Choose a breed:\\n"]'),
  (82, 'rhino', 'Rhino', 'pets', 1, 277, 11, 77, 1, 1, '["catalog_pet_headline1"]', '["The Rhinoceros is an African herbivore that can weigh over a ton. It is proud and slightly aloof, but loyal and never let anything get in the way of a good time!","Name your pet:","Choose a colour:","Choose a breed:"]'),
  (83, 'spider', 'Spider', 'pets', 1, 277, 12, 95, 1, 1, '["catalog_pet_headline1"]', '["One of the most feared creatures in nature, and perhaps the most misunderstood. The majority of Spiders have sharp fangs that inject venom into their prey- but don''t worry, these spiders won''t bite! Maybe...", "Name your pet:"]'),
  (84, 'turtle', 'Turtles', 'pets', 1, 277, 9, 126, 1, 1, '["catalog_pet_headline1"]', '["Anything but slow, these guys are ready to ride the waves and swim laps at your h hes!", "Name your Turtle:"]'),
  (86, 'frog', 'Frog', 'pets', 1, 277, 16, 97, 1, 1, '["catalog_pet_headline1"]', '["Cute, green and slimy! Frogs come in a variety of colours and can be found all over the world. They are great jumpers and make great pets, but are harder to hold onto than a supermodel in a tornado.", "Name your Frog:"]'),
  (87, 'dragon', 'Dragons', 'pets', 1, 277, 6, 109, 1, 1, '["catalog_pet_headline1"]', '["Keepers of the Dragon, beware...their history is legendary... With their fiery breath and scaly skin, these mythical creatures are nothing but fierce!", "Name your Dragon:"]'),
  (93, 'bunny_manic', 'Bunny - Manic', 'pets', 1, 277, 99, 149, 1, 0, '["catalog_pet_headline1"]', '["One of the most feared creatures in nature, and perhaps the most misunderstood. The majority of Spiders have sharp fangs that inject venom into their prey- but don''t worry, these spiders won''t bite ! Maybe...", "Name your pet:"]'),
  (94, 'pigeon_wise', 'Pigeon - Wise', 'pets', 1, 277, 99, 2, 1, 0, '[]', '[]'),
  (95, 'pigeon_cunning', 'Pigeon - Cunning', 'pets', 1, 277, 99, 2, 1, 0, '[]', '[]'),
  (96, 'monkey_evil', 'Monkey - Evil', 'pets', 1, 277, 99, 167, 1, 0, '[]', '[]'),
  (98, 'terrier_puppies', 'Terrier Puppies', 'pets', 1, 277, 5, 228, 1, 0, '["catalog_pet_headline1"]', '[]'),
  (99, 'kittens', 'Kittens', 'pets', 1, 277, 2, 228, 1, 0, '["catalog_pet_headline1"]', '["Leaping their way around the Hotel, these fluffy furballs are here to steal your heart...and your yarn!", "Name your pet:"]'),
  (100, 'puppies', 'Puppies', 'pets', 1, 277, 1, 228, 1, 0, '["catalog_pet_headline1"]', '["So soft and cuddly, these playful pups are certain to melt your heart. From Labradors to Dalmatians, there''s a breed for everyone!", "Name your pet:"]'),
  (101, 'piglets', 'Piglets', 'pets', 1, 277, 3, 228, 1, 0, '["catalog_pet_headline1"]', '["OINK! Partial to a good roll in the mud, these playful piggies have trotted into the hotel and are ready for fun!", "Name your pet:"]'),
  (103, 'coral_kingdom_crackables', 'Coral Kingdom Crackables', 'default_3x3', 1, 669, 9999, 42, 1, 1, '[]', '[]'),
  (104, 'drago', 'Drago', 'default_3x3', 1, 209, 4, 110, 1, 1, '["drago_catalog_header2","drago_catalog_teaser2"]', '["Dungeon furniture, the perfect range to create your torturous cellars!"]'),
  (105, 'dark_pura', 'Dark Pura', 'default_3x3', 1, 568, 9, 48, 0, 1, '["puraheader","catalog_pura_teaser1"]', '["The cleanest, freshest range. You can almost hear it breathe cool and tranquility within your room."]'),
  (106, 'boutique', 'Boutique', 'default_3x3', 1, 209, 2, 74, 1, 1, '["boutique_catalog_01","boutique_catalog_teaser_01"]', '["The boutique range is just the thing if you want to own a high end fashion store in Milan, but are on a budget."]'),
  (107, '', 'Groups', 'guilds', 1, 25, 99, 36900, 1, 1, '["catalog_groups_en","catalog_groupsteaser_en"]', '["Habbo Groups are a great way to stay in touch with your friends and share your interests with others. Each Group has a homeroom that can be decorated by other Group members, members can also purchase exclusive Group Furni that can be customised with your Group colours!", "* Get together with people you get together with!\\r\\n* Co-op room decorating for group members\\r\\n* Show off your group badge!\\r\\n* Get some neat Furni in your group''s colours!", "What''s So Great About Habbo Groups?"]'),
  (108, 'group_furni', 'Group Furni', 'guild_custom_furni', 1, 107, 1, 28, 1, 1, '["catalog_groups_en", "guild_custom_furni"]', '["Show off your Group spirit with the new customisable Furni. Select your Group and then get your furni in your Groups colours."]'),
  (109, 'youtube', 'Youtube', 'default_3x3', 1, 209, 25, 188, 1, 1, '["catalog_header_tv","yttv"]', '["Remember when Habbo had YouTube TVs? Well it can again, with KrewsTube! Check it out at krews.org"]'),
  (110, 'vikings', 'Vikings', 'default_3x3', 1, 209, 23, 208, 1, 1, '["vikings_catalog_header","catalog_teaser_vikings"]', '["From weapon racks and heads on spikes, to ornate hand-carved wooden chairs and benches. This furni has everything you need and more to create the Viking village of your dreams. With furni available in clan colours, you can display your true loyalty with pride!"]'),
  (111, '0', 'Palooza', 'default_3x3', 1, 209, 3, 227, 1, 1, '["catalog_teaser_palooza","catalog_teaser_palooza"]', '["Create your own stage and outdoor festival area. We''ve got stages, fencing and even vending machines!"]'),
  (112, 'wild_wild_west', 'Wild Wild West', 'default_3x3', 1, 209, 24, 229, 1, 1, '["catalog_header_wwest","catalog_teaser_wildwest"]', '["From the Shoot''em Up Saloon to the Sheriff''s Office, and all the floor tiles, cacti and tumbleweeds in between...Wild West furni has made it''s way to town."]'),
  (113, 'club_nx', 'Club NX', 'default_3x3', 1, 387, 4, 264, 1, 1, '["catalog_header_classics","catal_fp_pic5"]', '["On Habbo, there is a door at the top next to the bar that leads to Hallway 2."]'),
  (114, 'habbo_university', 'Habbo University', 'default_3x3', 1, 209, 8, 230, 1, 1, '["university_new_furni_catalog_header","university_catalog_teaser"]', '["From pink and flowery, to hipster chic - Every Habbo has a style."]'),
  (115, 'toys_and_accessories', 'Pet Accessories', 'default_3x3', 1, 277, 81, 199, 1, 1, '["catalog_pet_headline2","catalog_teaser_pettoys"]', '["The baby pets are here! Take good care of them and keep them happy with our exciting range of food and toys!", "Get some nice accessories for your pet."]'),
  (116, 'attic', 'Attic', 'default_3x3', 1, 209, 1, 242, 1, 1, '["attic15_catalog_header","attic15_catalog_teaser"]', '["From idueaky floor boards to ancient furniture, the Attic 2015 furniture is now here!"]'),
  (118, 'neo-habbo', 'Neo-Habbo', 'default_3x3', 1, 209, 14, 254, 1, 1, '["catalog_header_cpunk15","old_cypunk"]', '["Light-filled cityscapes and brightly lit skycrapers looming ovehead... This is the dark, dark furni line of the future. The future is called CyberPunk."]'),
  (119, 'nft', 'Imperial Mode', 'default_3x3', 1, 1072, 9, 39, 1, 1, '[]', '[]'),
