  (159, 'infobus', 'Infobus', 'default_3x3', 1, 387, 15, 264, 1, 1, '["catalog_header_classics","catal_fp_pic5"]', '["The famous Infobus was only ever opened when staff were hosting events or discussions, whereas the park was always open."]'),
  (160, 'game_hub', 'Game Hub', 'default_3x3', 1, 387, 7, 264, 1, 1, '["catalog_header_classics","catal_fp_pic5"]', '["This room was the main collaboration shown of games and events between users and official Habbo staff."]'),
  (161, 'paris', 'Paris', 'default_3x3', 1, 209, 17, 261, 1, 1, '["paris_header","paris_teaser"]', '["Always wanted to build a Paris designed room? Now is your chance with this brand new set of Paris furniture."]'),
  (162, 'hall_of_habbo', 'Hall of Habbo', 'default_3x3', 1, 387, 9, 264, 1, 1, '["catalog_header_classics","catal_fp_pic5"]', '["It is the least used Public Room, and features users who have won various competitions."]'),
  (163, 'groups_forums', 'Groups Forums', 'guild_forum', 1, 107, 2, 207, 1, 1, '["catalog_groups_en"]', '["Group Forums are here!", "<b><font color=\\"#0e3f52\\" size=\\"16\\">What are Group Forums?</font></b>\\r\\n\\r\\nForums allow you to effortlessly post, comment and discuss topics freely, without even leaving the Hotel!\\n\\n<i><b><font color=\\"#0e3f52\\" size=\\"16\\">Who can start a forum? </font></b></i>\\n\\nOnly a group owner can start a forum for their group.\\n\\n<i><b><font color=\\"#0e3f52\\" size=\\"16\\">Do I need a Forum Terminal?</font></b></i>\\n\\nYes - In order to start a Group Forum the group owner must first purchase a forum terminal for the group.\\n\\n\\nFind out more about Group Forums <a href=\\"event:habbopages/forums\\">here</a>.\\n\\nPlease note, we will continue to add more functionalities to this feature in the near future."]'),
  (164, 'usva_yellow', 'USVA - Yellow', 'default_3x3', 1, 60, 5, 48, 1, 1, '["catalog_header_USVA","Catalog_teaser_USVA"]', '["With a great range of colours and new stacking possibilities, you''ll love building and creating structures with the new USVA Furni line!"]'),
  (165, 'usva_green', 'USVA - Green', 'default_3x3', 1, 60, 4, 48, 1, 1, '["catalog_header_USVA","Catalog_teaser_USVA"]', '["With a great range of colours and new stacking possibilities, you''ll love building and creating structures with the new USVA Furni line!"]'),
  (166, 'usva__red', 'USVA -  Red', 'default_3x3', 1, 60, 3, 48, 1, 1, '["catalog_header_USVA","Catalog_teaser_USVA"]', '["With a great range of colours and new stacking possibilities, you''ll love building and creating structures with the new USVA Furni line!"]'),
  (167, 'usva__blue', 'USVA -  Blue', 'default_3x3', 1, 60, 1, 48, 1, 1, '["catalog_header_USVA","Catalog_teaser_USVA"]', '["With a great range of colours and new stacking possibilities, you''ll love building and creating structures with the new USVA Furni line!"]'),
  (168, 'usva__pink', 'USVA -  Pink', 'default_3x3', 1, 60, 2, 48, 1, 1, '["catalog_header_USVA","Catalog_teaser_USVA"]', '["With a great range of colours and new stacking possibilities, you''ll love building and creating structures with the new USVA Furni line!"]'),
