  (195, 'white_diner', 'White Diner', 'default_3x3', 1, 43, 5, 204, 1, 1, '["diner","catalog_diner_teaser_en"]', '["Originally from the 50''s this furni has been refurbished and put right into the catalogue! Use this with the Kitchen range for ultimate diner experience!"]'),
  (196, 'picnic', 'Picnic - Modern', 'default_3x3', 1, 387, 20, 264, 1, 1, '["catalog_header_classics","catal_fp_pic5"]', '["The remodel was debuted in February 2015, and was renamed from Picnic Area to Picnic."]'),
  (197, '', 'Wooden Block', 'default_3x3', null, 999, 23, 256, 1, 1, '[]', '[]'),
  (198, '', 'Neo-City', 'default_3x3', null, 999, 14, 256, 1, 1, '[]', '[]'),
  (199, 'jurassic_habbo', 'Jurassic Habbo', 'default_3x3', 1, 209, 10, 260, 1, 1, '["dino_header","dino_teaser"]', '["The creatures of the Primeval times are back! With this furni line you can let pure space in a prehistorican shine!"]'),
  (209, '', 'Furni By Line', 'pets', 1, 2, 4, 18755, 0, 1, '["furni_for_colection"]', '[]'),
  (210, '', 'Gradient Dragons', 'default_3x3', null, 999, 7, 256, 1, 1, '[]', '[]'),
  (211, 'add-ons', 'Add-Ons', 'default_3x3', 1, 218, 6, 85, 1, 1, '["catalog_wired_header5_en","ctlg_pic_wired_support_furniture"]', '["Use these simple Furni to bring extra spice to your Wired room. These are basic Furni, so you will still need Triggers, Effects and Conditions to make them work!", "Use Triggers, Effects and Conditions to make these Furni work!"]'),
  (212, 'gardening', 'Garden', 'default_3x3', 1, 604, 7, 157, 1, 1, '["garden_catalog_header","garden_catalog_teaser"]', '["Be at one with nature!"]'),
  (213, 'greek_crackables', 'Greek Crackables', 'default_3x3', 1, 669, 9999, 42, 1, 1, '[]', '[]'),
  (214, 'stranded_jungle', 'Jungle', 'default_3x3', 1, 209, 10, 59, 1, 1, '["catalog_header_2016jungle","junglenewfurni"]', '["Step into a virtual world of survival, treacherous terrain and life-threatening tropical conditions... because the Stranded Jungle line is here!"]'),
  (215, '3', 'Black Holes', 'default_3x3', 1, 874, 4, 125, 0, 0, '["catalog_blackhole_header_en","catalog_blackhole_teaser"]', '["Design your own custom room layouts with Stack Magic Tiles and Black holes. Stack your items to the ceiling or use them as dividers...the possibilities are endless!"]'),
  (217, 'sports', 'Sports', 'default_3x3', 1, 568, 22, 56, 1, 1, '["catalog_sports_headline1_br","catalog_sports_teaser1"]', '["The whistle blows, but there''s no track to practice on! Make your own before your trainer notices!"]'),
  (218, '', 'Wired Society', 'pets', 1, 5, 4, 18752, 1, 1, '["catalog_wired_header1","ctlg_pic_teaser_wired"]', '[]'),
  (219, '', 'Assorted Rares', 'default_3x3', null, 999, 1, 256, 1, 1, '[]', '[]'),
  (220, '', 'Marketplace', 'pets', 1, 2, 15, 69, 1, 1, '["catalog_marketplace_header_en","catalog_note_marketplace"]', '["Habbo Marketplace is a convenient and safe way to buy and sell items in Habbo.","How does the Habbo Marketplace work?","Buying items: Browse for the item you want to buy on the Marketplace Offers page and click Buy. We guarantee you''ll get the item at the cheapest price available at the moment of purchase. No requirements needed.\\r\\n\\r\\nSelling items: You can sell any item which is tradable by selecting the item in your inventory and clicking on ''Sell in Marketplace''. You also can use items currently in the Shop.\\r\\n\\r\\nNOTE: you can only sell 250 furni at a time.\\r\\n\\r\\nRequirements: To sell your Furni in the Marketplace you''ll need a Trading Pass, which you can get completing the first steps of the Talent Track."]'),
  (221, '', 'Assorted Dragons', 'default_3x3', null, 999, 1, 256, 1, 1, '[]', '[]'),
  (222, '', 'Recoloured Shapes', 'pets', 1, 1906, 1, 952, 0, 1, '["block_header","ctlg_bclub_note"]', '["1 Block... 2 Block... Red Block... Blue Block!","1 Block... 2 Block... Red\\r\\nBlock... Blue Block!","\\r\\n\\r\\nWith dozens of all the colours and patterns to choose from, you can really let your creativity run wild!\\r\\nExclusive to Builders Club."]'),
  (223, '2', 'Backgrounds', 'default_3x3', 1, 874, 1, 206, 1, 1, '["catalog_header_easter14_001","catalog_shal_teaser_da"]', '["Set the scene in your room properly with one of these backgrounds."]'),
  (224, '9', 'Teleports', 'default_3x3', 1, 568, 9, 120, 1, 1, '["catalog_doors_headline1","catalog_door_a"]', '["Beam yourself from one room to another with our space-age teleports. Buy a pair, put one in each room and you''ve got your own suite! IMPORTANT: teleports are always sold in pairs except for the Random Banzai Teleport.", "Click on an item for details."]'),
  (225, '', 'Trophies', 'trophies', 1, 568, 0, 221, 1, 1, '["trophies"]', '["Everyone''s a winner, baby! And now you can reward them all with our fabulous glittering array of bronze, silver and gold trophies.\\n\\nFirst choose the trophy model by click the arrows. Then select the metal. Type your inscription below and we''ll engrave it on the trophy along with your name and today''s date.\\nRemember - it''s permanent!"]'),
  (226, '2020_alpine_heights', '2020 - Alpine Heights', 'default_3x3', 1, 374, 13, 181, 1, 1, '["catalog_easter_headline1","easternew"]', '["Setting up a campsite along the river, nothing better than nature. Make your perfect campsite today!"]'),
  (229, 'club_shop', 'HC Oldschool', 'default_3x3', 1, 3078, 2, 18762, 1, 1, '["catalog_header_hc","teaser_habboclub"]', '[]'),
  (230, '', 'Cait', 'default_3x3', 1, 8890, 3, 60111, 1, 1, '[]', '[]'),
  (231, 'wall_decorations', 'Flags', 'default_3x3', 1, 568, 8, 219, 1, 1, '["catalog_gallery_headline1","catalog_posters_teaser1"]', '["Adorn your walls with wondrous works of art, posters, plaques and wall hangings. The Gallery is bursting with items to suit all tastes, from kitsch to cool, traditional to modern."]'),
  (232, 'pterodactyl', 'Pterodactyl', 'pets', 1, 277, 4, 260, 0, 0, '["jurassic15_catalog_header","dino_pets"]', '["These pterrific pets have a fierce appearance with long talons and sharp teeth, but their sweet nature always shines through! Ultra laid-back, these ''flying lizards'' love nothing more than spending time with their owner, soaring through the Hotel skies and eating their favourite food...the humble kale leaf."]'),
  (233, '', 'Studyo', 'default_3x3', 1, 1267, 19, 60110, 1, 1, '[]', '[]'),
  (234, 'pet_equipment', 'Pet Equipment', 'default_3x3', 1, 277, 99, 226, 1, 1, '[]', '[]'),
  (235, 'monkey_furni', 'Monkey Furni', 'default_3x3', 1, 209, 13, 128, 1, 1, '["catalog_pet_headline1_en","monkey_catalogue_teaser"]', '["Get exclusive Habbo Furni for your very own Pet Monkey!"]'),
  (236, '', 'Coe', 'default_3x3', 1, 8890, 3, 60111, 1, 1, '[]', '[]'),
  (237, '', 'Azure Chests', 'default_3x3', null, 999, 1, 256, 1, 1, '[]', '[]'),
  (240, '2013_love_locks', 'Functional Love Locks', 'default_3x3', 1, 376, 2, 62, 1, 1, '["catalog_header_val12","val14_lovelock3"]', '["Friendship Padlocks are Furni that show how special your friends are. You and your friend need to be in your room. Put the Padlock in the Room, click 2x on it, and confirm the action. Once closed, your friendship will be saved forever, even if you trade it!"]'),
  (241, '2014_l0-v3_machines', 'LOVE Machines', 'default_3x3', 1, 240, 12, 62, 1, 1, '["valentines_catalog_header","lovelock_s_promo"]', '["Put your love to the test! Lock in your Valentine for life with these Machines."]'),
  (242, 'saddles', 'Saddles', 'petcustomization', 1, 234, 4, 135, 1, 1, '["catalog_saddles_header2_en","sadddles"]', '["To use a saddle, place it in a room where you have at least one Horse. Double click the saddle and select what horse you want to ride After placing the saddle you can ride your Horse by clicking on it and selecting ''Ride''."]'),
  (243, 'dyes', 'Dyes', 'petcustomization', 1, 234, 5, 133, 1, 1, '["catalog_horsedyes_header2_en","dyes"]', '["Customize your horse with this selection of hair colours and body types. Each dye can also be added to your room as a piece of furniture. To use a dye place it to your room, double click on it and then select the horse you want to customise."]'),
  (244, 'hair_styles', 'Hair Styles', 'petcustomization', 1, 234, 6, 134, 1, 1, '["catalog_horsehairstyles2_header_en","hairs"]', '["Customize your horse and make him unique with this selection of hair styles.  Each style can also be added to your room as a piece of furniture. To use a hair style place it to your room, double click on it and then select the horse you want to customise."]'),
  (245, 'horse_jump', 'Horse Furni', 'default_3x3', 1, 209, 8, 226, 1, 1, '["catalog_header_jumping_en","catalog_teaser_horsejump"]', '["Take your horse jumping with these new Furni! Build a formidable race course to test your steed and your riding skills and challenge your friends!"]'),
  (246, 'monster_plants', 'Monster Plants', 'pets', 1, 209, 13, 153, 0, 0, '["catalog_header_mopla_01","ctlg_monster_note"]', '["Monster Plants can sure be a handful, this page gives you some extra advice on raising and looking after your monsterous brood.","Taking Care Of Your Plant","Your plants need to be tended regularly, or else they die. To ensure a healthy plant tend it every 30 hours\\nor so. If it dies, you can use the Revival potion to\\nbring it back to life.\\nBreeding\\nTo breed your plant you have to wait until it''s fully\\ngrown. Clicking Breed on the menu will show you\\nwhat other plants in the room are available to breed\\nwith."]'),
  (247, 'monster_plant_seeds', 'Monster Plant Seeds', 'default_3x3', 1, 246, 1, 156, 1, 1, '["catalog_header_mnstrSeeds","quest_teaser_monsterplants"]', '["Plant your seeds in your room and tend to keep them alive and healthy. After your plants have matured you can breed your plants to try and get leveled up offspring. Plants can only breed once without using the Rebreeding Potion."]'),
  (248, 'monster_plant_potions', 'Monster Plant Potions', 'default_3x3', 1, 246, 2, 155, 1, 1, '["monsterplantsprays_header","monsterplantspray_teaser"]', '["On this page you''ll find everything you need to take care of your plants: Plant Revival for when your plants die. Place potion to room, double click and select the plant you want to revive."]'),
  (249, 'wedding', 'Wedding', 'default_3x3', 1, 209, 24, 238, 1, 1, '["catalog_header_wedding","catalog_teaser_wedding"]', '["Now you can celebrate your great day with our wonderful selection of perfect furni for a wedding!"]'),
  (253, 'music_shop', 'Music Shop', 'default_3x3', 1, 568, 17, 4, 1, 1, '["music_header","catalog_djshop_teaser1"]', '["Let''s get loud! Place a Jukebox in your room, add some disks from the ''Habbo Hotel Hits'' list below and you''re ready to have a dance party!"]'),
  (254, 'habbo_hotel_hits', 'Habbo Hotel Hits', 'soundmachine', 1, 253, 2, 257, 1, 1, '["hotelhits_catalog_header","hotelhits_teaser"]', '["Turn up the volume with some cool new tunes for your room. Place a Jukebox in your room, get yourself some of these song discs and add them to your playlist!", "You need to be in a room to\\n\\"pre-listen\\" to the disks!"]'),
  (255, 'staff_wired', 'Staff Wired', 'default_3x3', null, 7, 12, 82, 1, 1, '[]', '[]'),
  (256, 'leaderboards', 'Leaderboards', 'default_3x3', 1, 218, -1, 221, 1, 1, '["wiredleaderboards_catalog_header","wiredleaderboards_teaser"]', '["The High Score furni to keep track of scores given in your games and displays them in your room.", "Click an item for details"]'),
